output.raw:
{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": ["C"],
      "content": "Hey, I'm working on getting a triangle for my order. Since you have the specialty triangle, maybe we can trade? I can produce squares if needed, but I'm thinking we could split the work."
    }
  },
  "rationale": "C has the specialty triangle and needs to fulfill their order, so a direct trade negotiation makes sense to align interests and reduce production costs for both of us."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on getting a circle for my order. Since you make circles, maybe you can sell me one? I can pay a fair price, like $20 or so."
    }
  },
  "rationale": "I need a circle to fulfill my order, and A has the specialty shape. Starting a direct conversation to propose a trade makes sense and aligns with my outgoing, cooperative nature."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm working on getting a square for my order. Since you're the specialist in squares, I was wondering if you'd be open to trading one of your squares for a circle? I can offer $25 if that works for you."
    }
  },
  "rationale": "I need a square to fulfill my order, and B has the specialty shape. A direct, low-pressure trade proposal at a fair price makes sense to start cooperation."
}

